class Counter:
    def __init__(self) -> None:
        self._mailbox: asyncio.Queue[int | None] = asyncio.Queue(maxsize=100)  # bounded
        self._count = 0

    async def run(self) -> None:                 # the actor: one message at a time
        while (delta := await self._mailbox.get()) is not None:
            self._count += delta

    def tell(self, delta: int) -> None:
        self._mailbox.put_nowait(delta)          # QueueFull if the actor is saturated
